def generate(rng):
    H,W=9,13
    g=[[0]*W for _ in range(H)]
    # fixed-size 2x2 anchor object, with a varied position
    r8=rng.randint(1,6); c8=rng.randint(2,7)
    for r in range(r8,r8+2):
        for c in range(c8,c8+2): g[r][c]=8
    # generate a connected 2-colored object to the right, usually one-cell gap
    r0=rng.randint(max(0,r8-1), min(6,r8+1)); c0=rng.randint(c8+3, min(10,c8+6))
    cells={(r0,c0)}
    for _ in range(rng.randint(4,10)):
        r,c=rng.choice(tuple(cells)); dr,dc=rng.choice([(1,0),(-1,0),(0,1),(0,-1)])
